<?php require_once '../../conexion.php'; 
$sql = "SELECT p.*, doc.tipo_prenda, o.nro_orden_cotizacion FROM posicion p LEFT JOIN detalle_orden_compra doc ON p.id_detalle_orden_compra = doc.ID LEFT JOIN orden_compra o ON doc.id_orden_compra = o.ID ORDER BY p.ID DESC"; 
$posiciones = $pdo->query($sql)->fetchAll(PDO::FETCH_ASSOC); 
$prendas = $pdo->query("SELECT d.ID, o.nro_orden_cotizacion, d.tipo_prenda, d.talla FROM detalle_orden_compra d LEFT JOIN orden_compra o ON d.id_orden_compra = o.ID ORDER BY d.ID DESC")->fetchAll(PDO::FETCH_ASSOC);
?>
