<main class="main-content"><header class="header"><h1>Posicionamiento de Detalles en Prenda</h1><div class="search-bar"><input type="text" id="buscador" onkeyup="buscarTabla()" placeholder="Buscar elemento..."></div></header>
<div class="card"><div class="card-header"><h3>Total: <?= count($posiciones) ?> posiciones</h3><div style="display:flex;gap:10px;"><button class="btn btn-primary" onclick="agregarFilaVacia()"><i class="ph-bold ph-plus"></i> Añadir Posición</button></div></div>
