<tbody id="cuerpoTabla">
<?php foreach($posiciones as $p): $txt_prenda = "Ord: " . ($p['nro_orden_cotizacion']??'') . " - " . ($p['tipo_prenda']??''); ?>
<tr id="row-<?= $p['ID'] ?>"><td>#<?= $p['ID'] ?></td><td data-campo="id_detalle_orden_compra" data-idval="<?= $p['id_detalle_orden_compra'] ?>" data-text="<?= htmlspecialchars($txt_prenda) ?>" style="font-weight:bold; color:var(--color-green);"><?= htmlspecialchars($txt_prenda) ?></td><td data-campo="ubicacion"><?= htmlspecialchars($p['ubicacion'] ?? '') ?></td><td data-campo="elemento" style="color:var(--color-red); font-weight:bold;"><?= htmlspecialchars($p['elemento'] ?? '') ?></td><td data-campo="observacion"><?= htmlspecialchars($p['observacion'] ?? '') ?></td><td style="text-align:center;white-space:nowrap;"><button class="action-btn" onclick="editarFila('<?= $p['ID'] ?>')" id="btn-edit-<?= $p['ID'] ?>"><i class="ph-fill ph-pencil-simple"></i></button> <button class="action-btn text-red" onclick="eliminarFila('<?= $p['ID'] ?>')"><i class="ph-fill ph-trash"></i></button> <button class="action-btn text-green" onclick="guardarFila('<?= $p['ID'] ?>')" id="btn-save-<?= $p['ID'] ?>" style="display:none;"><i class="ph-bold ph-check"></i></button> <button class="action-btn text-red" onclick="cancelarEdicion('<?= $p['ID'] ?>')" id="btn-cancel-<?= $p['ID'] ?>" style="display:none;"><i class="ph-bold ph-x"></i></button></td></tr>
<?php endforeach; ?>
</tbody></table></div></main>
<div class="modal-overlay" id="modalPrenda"><div class="modal-box"><div class="modal-header"><span>Seleccionar Prenda de la Orden</span><button class="modal-close" onclick="cerrarModal()"><i class="ph-bold ph-x"></i></button></div><input type="text" class="modal-search" id="searchPrenda" onkeyup="filtrarLista('searchPrenda', 'tablePrenda')" placeholder="🔍 Buscar por Orden o Prenda..."><div class="modal-table-container"><table class="modal-table" id="tablePrenda"><thead><tr><th>ID Prenda</th><th>Nro Orden (Cotización)</th><th>Tipo Prenda</th><th>Talla Std</th><th>Acción</th></tr></thead><tbody>
<?php foreach($prendas as $p): $txt = "Ord: " . ($p['nro_orden_cotizacion']??'') . " - " . ($p['tipo_prenda']??''); ?>
<tr><td style="font-weight:bold;">#<?= $p['ID'] ?></td><td><?= htmlspecialchars($p['nro_orden_cotizacion']??'') ?></td><td><?= htmlspecialchars($p['tipo_prenda']??'') ?></td><td><?= htmlspecialchars($p['talla']??'') ?></td><td style="text-align:right;"><button class="btn-elegir" onclick="seleccionarItem('<?= $p['ID'] ?>', '<?= addslashes(htmlspecialchars($txt)) ?>')">Elegir</button></td></tr>
<?php endforeach; ?>
</tbody></table></div></div></div>
<script>
let datosOrig={}; let filaActivaModal=null; const campos=['id_detalle_orden_compra','ubicacion','elemento','observacion'];
function abrirModal(idFila) { filaActivaModal = idFila; document.getElementById('modalPrenda').style.display='flex'; } function cerrarModal() { document.getElementById('modalPrenda').style.display='none'; }
function seleccionarItem(idVal, txtVal) { document.getElementById(`input-${filaActivaModal}-id_detalle_orden_compra`).value = idVal; document.getElementById(`text-${filaActivaModal}-id_detalle_orden_compra`).innerText = txtVal; cerrarModal(); }
function filtrarLista(inp, tab) { let f=document.getElementById(inp).value.toLowerCase(), r=document.getElementById(tab).getElementsByTagName('tr'); for(let i=1; i<r.length; i++) r[i].style.display = r[i].innerText.toLowerCase().includes(f) ? "" : "none"; }
function editarFila(id){datosOrig[id]={};document.querySelectorAll(`#row-${id} td[data-campo]`).forEach(td=>{let c=td.getAttribute('data-campo');datosOrig[id][c]=td.innerHTML; if(c === 'id_detalle_orden_compra'){td.innerHTML = `<div class="selector-box" onclick="abrirModal('${id}')"><span id="text-${id}-${c}">${td.getAttribute('data-text')}</span> <i class="ph-bold ph-caret-down"></i></div><input type="hidden" id="input-${id}-${c}" value="${td.getAttribute('data-idval')}">`;} else {td.innerHTML=`<input type="text" class="form-control" id="input-${id}-${c}" value="${td.innerText}">`;}});document.getElementById(`btn-edit-${id}`).style.display='none'; document.getElementById(`btn-save-${id}`).style.display='inline-block'; document.getElementById(`btn-cancel-${id}`).style.display='inline-block';}
function cancelarEdicion(id){if(id==='nuevo')return document.getElementById('row-nuevo').remove();document.querySelectorAll(`#row-${id} td[data-campo]`).forEach(td=>td.innerHTML=datosOrig[id][td.getAttribute('data-campo')]);document.getElementById(`btn-edit-${id}`).style.display='inline-block';document.getElementById(`btn-save-${id}`).style.display='none';document.getElementById(`btn-cancel-${id}`).style.display='none';}
function agregarFilaVacia(){if(document.getElementById('row-nuevo')) return; let tr=document.createElement('tr'); tr.id='row-nuevo'; tr.style.backgroundColor='#f0fdf4'; tr.innerHTML=`<td>Nuevo</td><td data-campo="id_detalle_orden_compra"><div class="selector-box" onclick="abrirModal('nuevo')"><span id="text-nuevo-id_detalle_orden_compra">🔍 Elegir Prenda...</span></div><input type="hidden" id="input-nuevo-id_detalle_orden_compra"></td><td data-campo="ubicacion"><input type="text" class="form-control" id="input-nuevo-ubicacion"></td><td data-campo="elemento"><input type="text" class="form-control" id="input-nuevo-elemento"></td><td data-campo="observacion"><input type="text" class="form-control" id="input-nuevo-observacion"></td><td style="text-align:center;"><button class="action-btn text-green" onclick="guardarFila('nuevo')"><i class="ph-bold ph-check"></i></button> <button class="action-btn text-red" onclick="cancelarEdicion('nuevo')"><i class="ph-bold ph-x"></i></button></td>`;document.getElementById('cuerpoTabla').prepend(tr);}
function guardarFila(id){let p = document.getElementById(`input-${id}-id_detalle_orden_compra`).value; if(!p) { Swal.fire('Alto', 'Debes usar el selector de prenda.', 'warning'); return; } let fd = new FormData(); fd.append('accion', id==='nuevo'?'crear':'editar'); if(id!=='nuevo') fd.append('id', id); campos.forEach(c => fd.append(c, document.getElementById(`input-${id}-${c}`).value)); fetch('crud.php', {method:'POST', body:fd}).then(r=>r.json()).then(d=>{ if(d.status==='success') location.reload(); });}
function eliminarFila(id){Swal.fire({title:'¿Borrar?',icon:'warning',showCancelButton:true,confirmButtonColor:'#E11D48'}).then((r)=>{if(r.isConfirmed){let fd=new FormData();fd.append('accion','eliminar');fd.append('id',id);fetch('crud.php',{method:'POST',body:fd}).then(r=>r.json()).then(d=>{if(d.status==='success')document.getElementById(`row-${id}`).remove();});}});}
function buscarTabla(){let i=document.getElementById("buscador").value.toLowerCase();document.querySelectorAll("#tablaDatos tbody tr").forEach(tr=>{if(tr.id!=='row-nuevo')tr.style.display=tr.innerText.toLowerCase().includes(i)?"":"none";});}
</script></body></html>